**Add optional secondary read pool support to the alloydb module.**

It is now possible to configure and create secondary read pools replicating from the secondary instance using the alloydb module. The configuration is same as existing primary read pool configuration but available under the `cross_region_replication`, e.g:

```
 module "my_alloydb" {
  # source         = "github.com/terraform-google-modules/cloud-foundation-fabric//modules/alloydb?ref=v48.0.0"
  source            = "../../modules/alloydb"
  project_id     = var.project_id
  location       = var.location_primary
  cluster_name   = "${var.name}-primary"
  instance_name  = "${var.name}-primary"
  machine_config = {
    cpu_count    = 2
    machine_type = var.machine_type
  }
  initial_user = {
    password = var.initial_password
  }
  network_config = {
    psc_config = { allowed_consumer_projects = [ data.google_project.client_project.number ] }
  }
  database_version = var.database_version
  read_pool = {
    "${var.name}-read-pool" = {
      node_count = var.read_pool_count
    }
  }
  cross_region_replication = {
    enabled = true
    region  = var.location_secondary
    secondary_cluster_name = "${var.name}-secondary"
    secondary_instance_name = "${var.name}-secondary"
    read_pool = {
      "${var.name}-secondary-read-pool" = {
        node_count = var.read_pool_count
      }
    }
  }

  # Set to true in the real production environment
  deletion_protection = false
